function benutzer_gruppe_id_nach_bezeichnung(string $bezeichnung): ?int
{
    $db = datenbank_verbindung();
    if (!$db) {
        return null;
    }

    $abfrage = $db->prepare('SELECT id FROM benutzer_gruppen WHERE bezeichnung = :bezeichnung LIMIT 1');
    $abfrage->execute(['bezeichnung' => $bezeichnung]);
    $ergebnis = $abfrage->fetch();

    return is_array($ergebnis) ? (int)$ergebnis['id'] : null;
}

